pping": [], "confirmer": "", "actionTypeId": ""}, "actionTypeId": null}, "R-021": {"id": "R-021", "core": true, "desc": "每周一按销售额（不含税）周环比计算，下降超过 15% 的门店产生告警。", "expr": "wow(gmv@v3(store, week)) < -0.15", "name": "门店销售额环比下降", "conds": [{"op": "<", "field": "销售额（不含税）周环比", "value": "−15.0%", "metric": "gmv", "metricVer": 3}], "level": "中", "logic": "且", "owner": "陈立军", "dedupe": "规则 + 门店 + 周", "output": "告警", "status": "已发布", "weekly": 9, "objKind": "store", "trigger": {"cron": "0 9 * * 1", "kind": "定时", "text": "每周一 09:00"}, "version": 2, "cooldown": "7 天", "autoStage": {"enabled": false, "mapping": [], "confirmer": "", "actionTypeId": ""}, "actionTypeId": null}, "R-023": {"id": "R-023", "core": false, "desc": "待支付超过 30 分钟仍未自动取消的订单，提示订单运营核查。", "expr": "order.status = \\"待支付\\" AND minutes_since(order.createdAt) > 30", "name": "订单支付超时未取消", "conds": [{"op": "=", "field": "订单状态", "value": "待支付"}, {"op": ">", "field": "下单时长", "value": "30 分钟"}], "level": "低", "logic": "且", "owner": "孙浩然", "dedupe": "规则 + 订单", "output": "通知", "status": "已发布", "weekly": 140, "objKind": "order", "trigger": {"cron": "*/15 * * * *", "kind": "定时", "text": "每 15 分钟"}, "version": 2, "cooldown": "不重复", "autoStage": {"enabled": true, "mapping": [{"from": "命中.对象", "param": "订单"}, {"from": "固定值：已取消", "param": "目标状态"}, {"from": "固定值：系统同步乱序", "param": "修正原因"}], "confirmer": "订单运营组 孙浩然", "actionTypeId": "correct_order_status"}, "actionTypeId": "correct_order_status"}, "R-025": {"id": "R-025", "core": false, "desc": "已停用：与 R-021 重复，保留历史命中记录。", "expr": "consecutive_days(gmv@v3(store, day) / target(store, day) < 0.9) >= 3", "name": "门店销售额连续 3 天低于目标", "conds": [{"op": "<", "field": "销售额（不含税）/ 日目标", "value": "90.0%（连续 3 天）", "metric": "gmv", "metricVer": 3}], "level": "中", "logic": "且", "owner": "陈立军", "dedupe": "规则 + 门店", "output": "通知", "status": "已停用", "weekly": 0, "objKind": "store", "trigger": {"cron": "0 9 * * *", "kind": "定时", "text": "每天 09:00"}, "version": 1, "cooldown": "7 天", "autoStage": {"enabled": false, "mapping": [], "confirmer": "", "actionTypeId": ""}, "actionTypeId": null}, "R-026": {"id": "R-026", "core": false, "desc": "近 14 天缺货超过 2 次的商品，提示供应链计划员上调安全库存。", "expr": "count(stockout, 14d) > 2", "name": "安全库存设置偏低", "conds": [{"op": ">", "field": "近 14 天缺货次数", "value": "2"}], "level": "低", "logic": "且", "owner": "周晓峰", "dedupe": "规则 + 商品 + 门店", "output": "通知", "status": "已发布", "weekly": 12, "objKind": "product", "trigger": {"cron": "0 5 * * 1", "kind": "定时", "text": "每周一 05:00"}, "version": 1, "cooldown": "14 天", "autoStage": {"enabled": true, "mapping": [{"from": "命中.对象", "param": "商品"}, {"from": "固定值：频繁缺货", "param": "原因"}], "confirmer": "供应链计划员 周晓峰", "actionTypeId": "set_safety_stock"}, "actionTypeId": "set_safety_stock"}, "R-027": {"id": "R-027", "core": false, "desc": "每周六晚按大区汇总复购客户销售额（不含税），周环比下降超过 8% 时通知营销经理，并把复购召回券暂存到动作中心待确认。", "expr": "wow(gmv@v3(region, week | customer.isRepeat)) < -0.08", "name": "大区复购客户销售额周环比下降", "conds": [{"op": "<", "field": "复购客户销售额（不含税）周环比", "value": "−8.0%", "metric": "gmv", "metricVer": 3}], "level": "中", "logic": "且", "owner": "吴佳", "dedupe": "规则 + 大区 + 周", "output": "通知", "status": "已发布", "weekly": 1, "objKind": "region", "trigger": {"cron": "0 22 * * 6", "kind": "定时", "text": "每周六 22:00（本周日至周六数据）"}, "version": 1, "cooldown": "7 天", "autoStage": {"enabled": true, "mapping": [{"from": "命中.对象", "param": "大区"}, {"from": "大区内 60 天未复购会员", "param": "召回会员"}, {"from": "固定值：复购召回", "param": "召回活动"}, {"from": "固定值：满 99 减 15", "param": "券模板"}, {"from": "固定值：15.00", "param": "面额（元）"}, {"from": "固定值：99.00", "param": "使用门槛（元）"}, {"from": "固定值：14", "param": "有效天数"}, {"from": "固定值：小程序", "param": "发放渠道"}, {"from": "固定值：会员召回", "param": "预算科目"}, {"from": "固定值：60 天未复购", "param": "召回原因"}], "confirmer": "营销经理 吴佳", "actionTypeId": "issue_recall_coupon"}, "actionTypeId": "issue_recall_coupon"}, "SM-ORD": {"id": "SM-ORD", "core": true, "desc": "订单状态变更不在生命周期 v4 允许的迁移里时产生告警。", "expr": "(event.fromStatus, event.toStatus) NOT IN lifecycle(\\"SalesOrder\\", 4).transitions", "name": "订单状态非法迁移", "conds": [{"op": "∉", "field": "状态迁移（原 → 新）", "value": "生命周期 v4 合法迁移"}], "level": "高", "logic": "且", "owner": "孙浩然", "dedupe": "事件 ID", "output": "告警", "status": "已发布", "weekly": 31, "objKind": "order", "trigger": {"kind": "事件", "text": "订阅“订单状态变更”（OrderStatusChanged）", "filter": "全部", "eventId": "order_status_changed"}, "version": 4, "cooldown": "不重复", "autoStage": {"enabled": true, "mapping": [{"from": "事件.订单号", "param": "订单"}, {"from": "生命周期上一个合法状态", "param": "目标状态"}, {"from": "固定值：系统同步乱序", "param": "修正原因"}, {"from": "告警.ID", "param": "关联告警"}], "confirmer": "订单运营组 孙浩然", "actionTypeId": "correct_order_status"}, "actionTypeId": "correct_order_status"}}, "terms": {"K-001": {"id": "K-001", "calc": "会员.近90天有效订单数 = COUNT(订单) WHERE 订单.状态 ≠ 已取消 AND 下单时间 ∈ [截止日 − 89 天, 截止日]", "maps": "对象集「复购客户」", "name": "复购客户", "type": "术语", "owner": "孙浩然", "since": "v2026.08.2", "tries": ["上个月华东复购客户的销售额是多少", "老客客单价近 3 个月趋势", "各大区回头客占比"], "period": "2026-09-19 起（v2026.09.3）", "status": "已发布", "applies": [{"id": "member", "kind": "object-type", "name": "会员"}, {"id": "order", "kind": "object-type", "name": "订单"}, {"id": "gmv", "kind": "metric", "name": "销售额（不含税）"}], "filters": [{"cond": "≥ 2", "note": "问题里没写时间窗时默认 90 天", "field": "会员.近90天有效订单数"}, {"cond": "非空", "note": "散客订单不计入", "field": "订单.会员号"}], "history": [{"at": "2026-09-19 19:12", "by": "孙浩然", "cr": "CR-0002", "ver": "v2026.09.3", "change": "时间窗 30 天 → 90 天，与会员中心口径一致", "status": "生效中"}, {"at": "2026-08-12 10:20", "by": "孙浩然", "ver": "v2026.08.2", "change": "创建：30 天内有效订单 ≥ 2 的会员", "status": "已替换"}], "synonyms": ["回头客", "老客", "复购会员"], "updatedAt": "2026-09-19 19:12", "definition": "统计截止日前 90 天内，有效订单数 ≥ 2 的会员。非会员订单不参与复购判断。"}, "K-002": {"id": "K-002", "calc": "会员.注册天数 = 截止日 − 会员.注册日期 ≥ 365", "maps": "过滤条件「会员.注册天数 ≥ 365」", "name": "老会员", "type": "术语", "owner": "刘婷", "since": "v2026.08.2", "tries": ["老会员的积分兑换率", "老客上月消费金额"], "period": "长期有效", "status": "已发布", "applies": [{"id": "member", "kind": "object-type", "name": "会员"}], "filters": [{"cond": "≤ 截止日 − 365 天", "note": "", "field": "会员.注册日期"}], "history": [{"at": "2026-08-12 10:20", "by": "刘婷", "ver": "v2026.08.2", "change": "创建", "status": "生效中"}], "synonyms": ["老客", "老用户"], "updatedAt": "2026-08-12 10:20", "definition": "注册满 365 天的会员，不看是否复购。会员权益和积分活动按此口径圈人。"}, "K-003": {"id": "K-003", "calc": "会员.首单日期 ∈ 统计期", "maps": "过滤条件「会员.首单日期 ∈ 统计期」", "name": "新客", "type": "术语", "owner": "刘婷", "since": "v2026.08.2", "tries": ["本周各门店新客数", "双十一新客客单价"], "period": "长期有效", "status": "已发布", "applies": [{"id": "member", "kind": "object-type", "name": "会员"}, {"id": "order", "kind": "object-type", "name": "订单"}], "filters": [{"cond": "∈ 统计期", "note": "统计期取问题里的时间", "field": "会员.首单日期"}], "history": [{"at": "2026-08-12 10:20", "by": "刘婷", "ver": "v2026.08.2", "change": "创建", "status": "生效中"}], "synonyms": ["新会员", "首单客户"], "updatedAt": "2026-08-12 10:20", "definition": "首笔有效订单发生在统计期内的会员。"}, "K-004": {"id": "K-004", "calc": "门店.开业日期 ≤ 统计期起始 − 12 个月 AND 门店.状态 ≠ 闭店 AND 门店.最长停业天数（统计期） ≤ 30", "maps": "过滤条件（门店范围）", "name": "同店", "type": "业务规则", "owner": "陈立军", "since": "v2026.08.2", "tries": ["华东同店销售额同比", "上月可比门店客单价", "老店有效订单数环比"], "period": "长期有效", "status": "已发布", "applies": [{"id": "store", "kind": "object-type", "name": "门店"}, {"id": "gmv", "kind": "metric", "name": "销售额（不含税）"}, {"id": "order_cnt", "kind": "metric", "name": "有效订单数"}], "filters": [{"cond": "≤ 统计期起始 − 12 个月", "note": "开业满 12 个月", "field": "门店.开业日期"}, {"cond": "≠ 闭店", "note": "统计期内闭店的门店剔除", "field": "门店.状态"}, {"cond": "≤ 30", "note": "装修停业超过 30 天剔除", "field": "门店.最长停业天数"}], "history": [{"at": "2026-08-12 10:20", "by": "陈立军", "ver": "v2026.08.2", "change": "创建：开业满 12 个月", "status": "已替换"}], "synonyms": ["可比门店", "同店口径", "老店"], "updatedAt": "2026-10-17 20:45", "definition": "可比门店：统计期开始时已开业满 12 个月、统计期内未闭店、且没有连续 30 天以上的装修停业。用于同比、环比时剔除新店和闭店的影响。"}, "K-005": {"id": "K-005", "calc": "日期 ∈ 财务日历.大促区间；同比时与上一年同名大促对比，不按自然日对齐", "maps": "时间范围（按财务日历）", "name": "大促期", "type": "财务日历", "owner": "何静", "since": "v2026.08.2", "tries": ["大促期间华南销售额", "今年大促和去年比怎么样"], "period": "2026 财年", "status": "已发布", "applies": [{"id": "order", "kind": "object-type", "name": "订单"}, {"id": "promotion", "kind": "object-type", "name": "促销活动"}, {"id": "gmv", "kind": "metric", "name": "销售额（不含税）"}], "filters": [{"cond": "∈ 大促区间", "note": "含预热期", "field": "订单.下单日期"}], "history": [{"at": "2026-08-12 10:20", "by": "何静", "ver": "v2026.08.2", "change": "创建", "status": "已替换"}], "periods": [{"end": "2026-02-05", "name": "年货节", "note": "含春节前 2 周", "start": "2026-01-10"}, {"end": "2026-06-18", "name": "618", "note": "预热 5/25 起不计入", "start": "2026-06-01"}, {"end": "2026-11-11", "name": "双十一", "note": "含预售期", "start": "2026-10-20"}, {"end": "2026-12-12", "name": "双十二", "note": "", "start": "2026-12-08"}], "synonyms": ["大促", "促销季"], "updatedAt": "2026-10-09 22:03", "definition": "公司级大促活动的统计区间，含预热期。问题里只说“大促”时，取离提问日期最近的一次大促。"}, "K-007": {"id": "K-007", "calc": "财务月 = 财务日历.财务月（4-4-5 周）；财年 FY2026 = 2026-02-01 至 2027-01-30", "maps": "时间范围（按财务日历）", "name": "财年与财务月", "type": "财务日历", "owner": "何静", "since": "v2026.08.2", "tries": ["本财年累计销售额", "FY2026 Q3 毛利率"], "period": "FY2026", "status": "已发布", "applies": [{"id": "order", "kind": "object-type", "name": "订单"}, {"id": "gmv", "kind": "metric", "name": "销售额（不含税）"}, {"id": "gross_margin", "kind": "metric", "name": "毛利率"}], "filters": [], "history": [{"at": "2026-08-12 10:20", "by": "何静", "ver": "v2026.08.2", "change": "创建", "status": "生效中"}], "periods": [{"end": "2026-05-02", "name": "FY2026 Q1", "note": "4-4-5 周", "start": "2026-02-01"}, {"end": "2026-08-01", "name": "FY2026 Q2", "note": "", "start": "2026-05-03"}, {"end": "2026-10-31", "name": "FY2026 Q3", "note": "当前财季", "start": "2026-08-02"}, {"end": "2027-01-30", "name": "FY2026 Q4", "note": "", "start": "2026-11-01"}], "synonyms": ["财年", "财务月", "FY"], "updatedAt": "2026-08-12 10:20", "definition": "财年自 2 月 1 日开始，按 4-4-5 周划分财务月。问题里说“本财年”“财务 3 月”时按财务日历换算，说“3 月”时按自然月。"}, "K-008": {"id": "K-008", "calc": "对比区间 = 去年春节日期 + (本期日期 − 今年春节日期)", "maps": "同比方式", "name": "春节错期对比", "type": "业务规则", "owner": "何静", "since": "v2026.09.3", "tries": ["春节期间销售额同比"], "period": "每年 1 月 1 日至 2 月末", "status": "已发布", "applies": [{"id": "gmv", "kind": "metric", "name": "销售额（不含税）"}, {"id": "order_cnt", "kind": "metric", "name": "有效订单数"}], "filters": [], "history": [{"at": "2026-09-19 19:12", "by": "何静", "cr": "CR-0002", "ver": "v2026.09.3", "change": "创建", "status": "生效中"}], "synonyms": ["春节同比", "农历同比"], "updatedAt": "2026-09-19 19:12", "definition": "1–2 月做同比时按农历对齐：今年春节前后 N 天对比去年春节前后 N 天，避免春节落在不同月份造成的波动。"}, "K-009": {"id": "K-009", "calc": "订单.状态 ≠ 已取消", "maps": "过滤条件「订单.状态 ≠ 已取消」", "name": "有效订单", "type": "术语", "owner": "陈立军", "since": "v2026.08.2", "tries": ["昨天各门店有效单", "上周成交订单数"], "period": "长期有效", "status": "已发布", "applies": [{"id": "order", "kind": "object-type", "name": "订单"}, {"id": "order_cnt", "kind": "metric", "name": "有效订单数"}], "filters": [{"cond": "≠ 已取消", "note": "默认过滤，问题里说“全部订单”时不加", "field": "订单.状态"}], "history": [{"at": "2026-08-12 10:20", "by": "陈立军", "ver": "v2026.08.2", "change": "创建", "status": "生效中"}], "synonyms": ["有效单", "成交订单"], "updatedAt": "2026-10-25 10:18", "definition": "状态不是“已取消”的订单。退款不影响订单是否有效，金额在销售额里冲减。"}, "K-010": {"id": "K-010", "calc": "销售额 = SUM(订单行.不含税金额) − SUM(退款行.不含税退款金额 WHERE 退款完成时间 ∈ 统计期)", "maps": "计算说明（回答里注明）", "name": "退款冲减口径", "type": "口径说明", "owner": "陈立军", "since": "v2026.08.2", "tries": ["为什么昨天销售额比 POS 少"], "period": "长期有效", "status": "已发布", "applies": [{"id": "refund", "kind": "object-type", "name": "退款单"}, {"id": "gmv", "kind": "metric", "name": "销售额（不含税）"}], "filters": [], "history": [{"at": "2026-08-12 10:20", "by": "陈立军", "ver": "v2026.08.2", "change": "创建", "status": "已替换"}], "synonyms": ["退款冲减", "净销售"], "updatedAt": "2026-10-24 21:17", "definition": "销售额按退款完成时间冲减，冲减到退款完成当天，不回溯原订单日期。部分退款按退款行冲减。"}, "K-012": {"id": "K-012", "calc": "订单.渠道 ∈ {小程序, App, 美团到家, 京东到家}", "maps": "过滤条件「订单.渠道 ∈ 线上」", "name": "线上渠道", "type": "术语", 